function strategyProductRows(p){const labels=new Map,codes=new Map,points=(p.points||[]).map(point=>{const groups=new Map;(point.holdings||[]).forEach(h=>{const label=holdingLabel(h),indexed=label.match_status==='已匹配'&&!!label.product,product=indexed?label.product:h.name,item=groups.get(product)||{code:product,name:product,quantity:0,market_value:0,cost:0,valuation_gain:0,_has_cost:false,_has_gain:false,_fallback_price:null};labels.set(product,label);const productCodes=codes.get(product)||new Set;productCodes.add(h.code);codes.set(product,productCodes);if(Number.isFinite(Number(h.quantity)))item.quantity+=Number(h.quantity);if(Number.isFinite(Number(h.market_value)))item.market_value+=Number(h.market_value);if(Number.isFinite(Number(h.cost))){item.cost+=Number(h.cost);item._has_cost=true}if(Number.isFinite(Number(h.valuation_gain))){item.valuation_gain+=Number(h.valuation_gain);item._has_gain=true}if(Number.isFinite(Number(h.price)))item._fallback_price=Number(h.price);groups.set(product,item)});const holdings=[...groups.values()].map(h=>{h.price=h.quantity?h.market_value/h.quantity:h._fallback_price;h.cost=h._has_cost?h.cost:null;h.valuation_gain=h._has_gain?h.valuation_gain:null;delete h._has_cost;delete h._has_gain;delete h._fallback_price;return h});return Object.assign({},point,{holdings})}),current=new Set((points.length?points[points.length-1].holdings:[]).map(h=>h.code)),proxy=Object.assign({},p,{points}),rows=holdingReport(points,p.inception).filter(h=>current.has(h.code));return rows.map(h=>{h._label=labels.get(h.name)||holdingLabel(h);const metric=holdingMetric(proxy,h);return{fof:p.name,name:h.name,code:[...(codes.get(h.name)||[])].filter(Boolean).join(' / '),market:Number(h.market_value)||0,profit:Number(h.period_profit)||0,rate:metric.period,label:metric.label,status:h.status,indexed:metric.label.match_status==='已匹配'&&!!metric.label.product}})}
function strategyNameIndexIssues(){const issues=[],seen=new Set;report.filter(p=>p.status==='ok').forEach(p=>((p.last&&p.last.holdings)||[]).forEach(h=>{const label=holdingLabel(h);if(label.match_status==='已匹配'&&label.product)return;const key=p.name+'|'+h.name;if(seen.has(key))return;seen.add(key);issues.push({product_name:h.name,fof:p.name,code:h.code,match_status:label.match_status||'其他',reason:'未匹配到产品标签中的标准产品名称，策略组合暂按估值表产品名称索引并归入其他'})}));return issues}
