let globalStrategyFilters={primary:'',secondary:'',vehicle:'',department:''};
function globalStrategyFilterOptions(field){const values=new Set;report.filter(p=>p.status==='ok').forEach(p=>p.holdings.forEach(h=>{const label=holdingLabel(h);values.add(label[field]||'无')}));return[...values].sort((a,b)=>a.localeCompare(b,'zh-CN'))}
function globalStrategyFilterSelect(field,label){const current=globalStrategyFilters[field]||'',options=globalStrategyFilterOptions(field);return`<label>${label}<select data-strategy-filter="${field}" onchange="setGlobalStrategyFilter('${field}',this.value)"><option value="">全部</option>${options.map(value=>`<option value="${escapeHtml(value)}"${value===current?' selected':''}>${escapeHtml(value)}</option>`).join('')}</select></label>`}
