function underlyingChoices(p){return p.holdings.map(h=>({h,series:holdingSeries(p,h)})).filter(x=>x.series.length).sort((a,b)=>(b.h.market_value||0)-(a.h.market_value||0))}
function renderUnderlying(p){const choices=underlyingChoices(p),indices=[...new Set(choices.map(x=>holdingBenchmark(holdingLabel(x.h))).filter(Boolean))];window.underlyingState={p,choices,indices,selected:new Set(choices.slice(0,10).map(x=>x.h.code))};underlyingControls.innerHTML=`<button onclick="selectAllUnderlying(true)">全选</button><button onclick="selectAllUnderlying(false)">全不选</button>`+choices.map(x=>`<label><input type=checkbox data-code="${x.h.code}" ${window.underlyingState.selected.has(x.h.code)?'checked':''} onchange="toggleUnderlying(this.dataset.code,this.checked)">${x.h.name}</label>`).concat(indices.map(code=>`<label><input type=checkbox data-code="index:${code}" onchange="toggleUnderlying(this.dataset.code,this.checked)">${benchmarkIndex(code).name}</label>`)).join('');redrawUnderlying()}
function toggleUnderlying(code,checked){checked?window.underlyingState.selected.add(code):window.underlyingState.selected.delete(code);redrawUnderlying()}
function selectAllUnderlying(checked){const state=window.underlyingState;if(!state)return;state.selected=new Set(checked?state.choices.map(x=>x.h.code).concat(state.indices.map(code=>'index:'+code)):[]);underlyingControls.querySelectorAll('input[data-code]').forEach(input=>input.checked=state.selected.has(input.dataset.code));redrawUnderlying()}
function redrawUnderlying(){const state=window.underlyingState,c=document.getElementById('underlyingChart');if(!state||!c)return;const series=state.choices.filter(x=>state.selected.has(x.h.code)).map((x,i)=>{const base=x.series[0].price;return{name:x.h.name,color:STRATEGY_COLORS[i%STRATEGY_COLORS.length],points:x.series.map(p=>({date:p.valuation_date,value:p.price/base*100}))}});state.indices.filter(code=>state.selected.has('index:'+code)).forEach((code,i)=>{const item=benchmarkIndex(code),points=(item.points||[]).filter(x=>x.date>=state.p.first.valuation_date&&x.date<=state.p.last.valuation_date);if(points.length){const base=Number(points[0].close);series.push({name:item.name,color:STRATEGY_COLORS[(series.length+i)%STRATEGY_COLORS.length],points:points.map(x=>({date:x.date,value:Number(x.close)/base*100}))})}});underlyingLegend.innerHTML=series.map(s=>`<span class=legend-item><i class=legend-dot style="background:${s.color}"></i>${s.name}</span>`).join('');drawMultiSeries(c,series,'underlyingTip')}
function drawMultiSeries(c,series,tipId){const ctx=c.getContext('2d'),L=65,R=18,T=18,B=50,all=series.flatMap(s=>s.points);ctx.clearRect(0,0,c.width,c.height);if(!all.length){ctx.fillStyle='#68736d';ctx.fillText('请勾选至少一只底层产品',L,T+20);return}const dates=all.map(p=>p.date).sort(),start=new Date(dates[0]+'T00:00:00'),end=new Date(dates[dates.length-1]+'T00:00:00'),values=all.map(p=>p.value),min=Math.min(...values),max=Math.max(...values),span=max-min||1,w=c.width-L-R,h=c.height-T-B,x=d=>L+(new Date(d+'T00:00:00')-start)/Math.max(end-start,DAY)*w,y=v=>T+(max-v)/span*h;ctx.strokeStyle='#e2e8f0';for(let i=0;i<=4;i++){const yy=T+h*i/4;ctx.beginPath();ctx.moveTo(L,yy);ctx.lineTo(L+w,yy);ctx.stroke();ctx.fillStyle='#68736d';ctx.fillText((max-span*i/4).toFixed(1),8,yy+4)}series.forEach(s=>{ctx.strokeStyle=s.color;ctx.lineWidth=2;ctx.beginPath();s.points.forEach((p,i)=>i?ctx.lineTo(x(p.date),y(p.value)):ctx.moveTo(x(p.date),y(p.value)));ctx.stroke()});let tip=document.getElementById(tipId);if(!tip){tip=document.createElement('div');tip.id=tipId;tip.className='chart-tip';document.body.appendChild(tip)}c.onmousemove=e=>{const rect=c.getBoundingClientRect(),cx=(e.clientX-rect.left)*c.width/rect.width,target=new Date(start.getTime()+Math.max(0,Math.min(1,(cx-L)/w))*(end-start)),day=target.toISOString().slice(0,10),rows=series.map(s=>{const p=s.points.filter(q=>q.date<=day).slice(-1)[0];return p?`<span style="color:${s.color}">●</span> ${s.name}: ${p.value.toFixed(2)}`:null}).filter(Boolean);tip.innerHTML=`<b>${day}</b><br>${rows.join('<br>')}`;tip.style.display='block';tip.style.left=Math.min(e.clientX+14,window.innerWidth-tip.offsetWidth-8)+'px';tip.style.top=Math.min(e.clientY+14,window.innerHeight-tip.offsetHeight-8)+'px'};c.onmouseleave=()=>tip.style.display='none'}
function enhanceDetail(p){if(!p||p.status!=='ok')return;const headings=[...detail.querySelectorAll('h3')],target=headings.find(x=>x.textContent==='底层产品收益率贡献');if(target){target.insertAdjacentHTML('beforebegin',strategySection(p));const holdingHeading=headings.find(x=>x.textContent==='底层投资期间收益');if(holdingHeading)holdingHeading.textContent='持仓明细';drawStrategy(p);renderUnderlying(p)}}
