function escapeHtml(value){return String(value==null?'':value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function popup(title,body){const win=window.open('','_blank');if(!win){alert('浏览器阻止了新窗口，请允许弹出窗口。');return null}win.document.write(`<!doctype html><meta charset=utf-8><title>${escapeHtml(title)}</title><style>body{font:14px/1.55 system-ui,"Microsoft YaHei";margin:24px;color:#18201d}table{border-collapse:collapse;width:100%;font-size:12px}th,td{border:1px solid #d9ddd5;padding:6px;vertical-align:top}th{background:#eef3f8;position:sticky;top:0}input,select{padding:8px;margin:0 8px 12px 0}.sub{color:#68736d}.history-item,p{margin:8px 0}</style><h1>${escapeHtml(title)}</h1>${body}`);win.document.close();return win}
function protectedSystemDocHtml(data){if(data.format==='qa'){const items=((data.content||{}).items||[]);return items.map(item=>`<section class=system-qa-item><h2>${escapeHtml(item.question||'')}</h2>${(item.answer||[]).map(text=>`<p>${escapeHtml(text)}</p>`).join('')}</section>`).join('')||'<p>暂无内容</p>'}return `<pre class=system-history>${escapeHtml(data.content||'暂无内容')}</pre>`}
function openProtectedSystemDoc(documentName){const title=documentName==='history'?'历史改动':'系统QA',win=popup(title,`<style>.system-doc-login{max-width:420px;display:grid;gap:12px}.system-doc-login label{display:grid;gap:5px}.system-doc-login input{margin:0}.system-doc-login button{justify-self:start}.system-doc-error{color:#a13e35}.system-history{white-space:pre-wrap;overflow-wrap:anywhere;background:#f6f8fb;padding:16px;border-radius:10px}.system-qa-item{max-width:900px}.system-qa-item h2{font-size:18px;margin-top:20px}.system-qa-item p{padding:9px 12px;background:#f6f8fb;border-radius:8px}</style><form id=systemDocLogin class=system-doc-login><p>此内容使用独立的系统文档账号验证。</p><label>账号<input name=username autocomplete=username required autofocus></label><label>密码<input name=password type=password autocomplete=current-password required></label><button type=submit>验证并打开</button><div id=systemDocError class=system-doc-error aria-live=polite></div></form><div id=systemDocContent></div>`);if(!win)return;const form=win.document.getElementById('systemDocLogin');form.onsubmit=async event=>{event.preventDefault();const fields=new win.FormData(form),error=win.document.getElementById('systemDocError'),button=form.querySelector('button');button.disabled=true;error.textContent='正在验证…';try{const response=await fetch('/api/system-docs/access',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:fields.get('username'),password:fields.get('password'),document:documentName}),cache:'no-store'}),data=await response.json();if(!response.ok)throw new Error(data.error||('HTTP '+response.status));form.remove();win.document.getElementById('systemDocContent').innerHTML=protectedSystemDocHtml(data)}catch(exc){error.textContent=exc.message;button.disabled=false}}}
function openInfo(kind){if(kind==='计算口径'){popup(kind,structuredCalculationHtml());return}if(kind==='风险与米筐数据库'){popup(kind,databaseUsageHtml());return}if(kind==='维护与变更记录'){popup(kind,maintenanceUsageHtml());return}if(kind==='产品标签'){openLabelEditor();return}if(kind==='历史改动'){openProtectedSystemDoc('history');return}if(kind==='系统QA'){openProtectedSystemDoc('qa');return}if(kind==='代码指令'){const card=[...document.querySelectorAll('.info-card')].find(x=>x.querySelector('summary').textContent===kind);popup(kind,card?card.querySelector('.info-body').innerHTML:'暂无内容');return}openDataWindow(kind)}
function dataTable(rows,filter){const source=rows||[],header=source.length?[source[0]]:[],body=source.slice(1).filter(row=>!filter||row.some(v=>String(v||'').toLowerCase().includes(filter))),visible=header.concat(body);return`<table><tbody>${visible.map((row,i)=>`<tr>${row.map(v=>`<${i?'td':'th'}>${escapeHtml(v)}</${i?'td':'th'}>`).join('')}</tr>`).join('')}</tbody></table>`}
function openDataWindow(kind){const books=kind==='资金台账'?{'资金台账':RAW.ledger_tables||{}}:((RAW.labels||{}).workbooks||{}),names=[];Object.keys(books).forEach(book=>Object.keys(books[book]||{}).forEach(sheet=>names.push({book,sheet})));const extra=kind==='产品标签'?`<p class=sub>标签匹配结果可按状态筛选；歧义和未匹配产品统一归入“其他”。原始“股票”按敞口及策略描述转换为股票指增、股票中性或股票对冲。</p><select id=status><option value="">全部状态</option><option>已匹配</option><option>其他</option><option>歧义</option></select>`:'';const win=popup(kind,`${extra}<select id=sheet>${names.map((x,i)=>`<option value="${i}">${escapeHtml(x.book+' / '+x.sheet)}</option>`).join('')}</select><input id=search placeholder="搜索当前表"><div id=grid></div>`);if(!win)return;const render=()=>{if(kind==='产品标签'&&win.document.getElementById('status').value){const status=win.document.getElementById('status').value,rows=[['底层产品','原始一级标签','有效一级标签','二级标签','投资形式','状态','来源','匹配方式','分类依据'],...Object.entries((RAW.labels||{}).matches||{}).filter(x=>x[1].match_status===status).map(x=>[x[0],x[1].raw_primary,x[1].primary,x[1].secondary,x[1].vehicle,x[1].match_status,x[1].source,x[1].match_method,x[1].classification_basis])];win.document.getElementById('grid').innerHTML=dataTable(rows,win.document.getElementById('search').value.toLowerCase());return}const selected=names[Number(win.document.getElementById('sheet').value)]||{},rows=((books[selected.book]||{})[selected.sheet]||[]);win.document.getElementById('grid').innerHTML=dataTable(rows,win.document.getElementById('search').value.toLowerCase())};win.document.getElementById('sheet').onchange=render;win.document.getElementById('search').oninput=render;if(kind==='产品标签')win.document.getElementById('status').onchange=render;render()}
async function labelApi(method,path,body){const response=await fetch(path,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,cache:'no-store'}),data=await response.json().catch(()=>({error:'服务器返回格式错误'}));if(!response.ok)throw new Error(data.error||('HTTP '+response.status));return data}
