function quantile(values,q){const a=values.filter(Number.isFinite).slice().sort((x,y)=>x-y);if(!a.length)return null;const p=(a.length-1)*q,lo=Math.floor(p),hi=Math.ceil(p);return a[lo]+(a[hi]-a[lo])*(p-lo)}
function historicalVar(points,valueKey){const values=[];for(let i=1;i<points.length;i++){const a=Number(valueKey(points[i-1])),b=Number(valueKey(points[i]));if(a>0&&b>0)values.push(Math.log(b/a)*100)}return{count:values.length,values:[.9,.95,.99].map(c=>{const q=quantile(values,1-c);return{confidence:c,value:q==null?null:Math.max(0,-q)}})}}
function yieldVar(points){const values=[];for(let i=1;i<points.length;i++){const a=Number(points[i-1].yield),b=Number(points[i].yield);if(Number.isFinite(a)&&Number.isFinite(b))values.push((b-a)*10000)}return{count:values.length,values:[.9,.95,.99].map(c=>{const q=quantile(values,c);return{confidence:c,value:q==null?null:Math.max(0,q)}})}}
