function simpleTailVar(points,key,side){const values=[];for(let i=1;i<points.length;i++){const a=Number(points[i-1][key]),b=Number(points[i][key]);if(a>0&&b>0){const r=(b/a-1)*100;values.push(side==='up'?r:-r)}}return{count:values.length,values:[.9,.95,.99].map(c=>{const q=quantile(values,c);return{confidence:c,value:q==null?null:Math.max(0,q)}})}}
function curveTailVar(points,key){const values=[];for(let i=1;i<points.length;i++){const a=Number(points[i-1][key]),b=Number(points[i][key]);if(Number.isFinite(a)&&Number.isFinite(b))values.push((b-a)*10000)}return{count:values.length,values:[.9,.95,.99].map(c=>{const q=quantile(values,c);return{confidence:c,value:q==null?null:Math.max(0,q)}})}}
function allRiskFactorsHtml(){const r=RAW.risk||{},p=r.portfolio_var||{},rows=[],fmt=(x,u)=>x==null?'无法计算':Number(x).toFixed(2)+' '+u,add=(kind,name,points,latest,v,unit,source)=>rows.push(`<tr><td>${escapeHtml(kind)}</td><td>${escapeHtml(name)}</td><td>${escapeHtml(latest||'—')}</td><td>${points.length?(points[0].date+' → '+points[points.length-1].date):'暂无数据'}</td><td>${v.count}</td>${v.values.map(x=>`<td>${fmt(x.value,unit)}</td>`).join('')}<td>${escapeHtml(source||'—')}</td></tr>`);Object.values(r.indices||{}).sort((a,b)=>(a.code||'').localeCompare(b.code||'')).forEach(x=>{const q=x.points||[],z=q[q.length-1];add('股票价格指数',x.name||x.code,q,z?(Number(z.close).toFixed(2)+' / '+z.date):'',historicalVar(q,a=>a.close),'%','Wind Oracle数据库')});const cn=((r.yield_curves||{}).CN10Y)||{},cp=cn.points||[],cl=cp[cp.length-1];add('收益率曲线','中国国债10Y',cp,cl?((Number(cl.yield)*100).toFixed(4)+'% / '+cl.date):'',curveTailVar(cp,'yield'),'bp',cn.source);const us=((r.yield_curves||{}).US_TREASURY)||{},up=(us.points||[]).filter(x=>Number.isFinite(Number(x['10Y']))),ul=up[up.length-1];add('收益率曲线','美国国债10Y',up,ul?((Number(ul['10Y'])*100).toFixed(4)+'% / '+ul.date):'',curveTailVar(up,'10Y'),'bp',us.source);const fx=((r.exchange_rates||{}).USDCNY)||{},fp=fx.points||[],fl=fp[fp.length-1];add('汇率','USD/CNY（人民币升值不利）',fp,fl?(Number(fl.rate).toFixed(4)+' / '+fl.date):'',simpleTailVar(fp,'rate','down'),'%',fx.source);const carbon=((p.parameters||{}).carbon_price_points)||[],last=carbon[carbon.length-1];add('碳价代理','Excel统一碳价涨跌幅',carbon,last?(Number(last.price).toFixed(4)+'元/吨 / '+last.date):'',simpleTailVar(carbon,'price','down'),'%','本地《碳排放价格.xlsx》');return`<h2>一、历史模拟VaR风险因子总表</h2><p class=sub>股票指数、汇率和碳价以价格不利跌幅百分比展示；中美国债10Y收益率以不利上行bp展示。全部美元利率资产统一使用美国国债10Y VaR。碳价Excel的单一涨跌幅序列统一代理所有碳资产。各单位不可直接横向相加。</p><div style=overflow:auto><table><thead><tr><th>类别</th><th>指标</th><th>最新值 / 日期</th><th>样本区间</th><th>日变动样本</th><th>90% VaR</th><th>95% VaR</th><th>99% VaR</th><th>来源</th></tr></thead><tbody>${rows.join('')}</tbody></table></div>`}
function basisVar(points,tenor){const values=[];for(let i=1;i<points.length;i++){const a=points[i-1][tenor],b=points[i][tenor];if(a&&b&&Number.isFinite(a.value)&&Number.isFinite(b.value))values.push(b.value-a.value)}return{count:values.length,values:[.9,.95,.99].map(c=>{const q=quantile(values,1-c);return{confidence:c,value:q==null?null:Math.max(0,-q)}})}}
function riskIndex(label){const s=label.secondary||'';if(s.includes('沪深300'))return{code:'000300',future:'IF',proxy:false};if(s.includes('中证500'))return{code:'000905',future:'IC',proxy:false};if(s.includes('中证1000'))return{code:'000852',future:'IM',proxy:false};return{code:'000852',future:'IM',proxy:true}}
function riskCurrentHoldings(){const rows=[],labels=(RAW.labels||{}).matches||{};RAW.products.forEach(product=>{const point=(product.points||[]).slice(-1)[0];if(!point)return;(point.holdings||[]).forEach(h=>{const label=labels[h.name]||{primary:'其他',secondary:'其他'},mapped=riskIndex(label);let factors=null;if(label.primary==='股票指增')factors={index:1,basis:0,commodity:0};else if(label.primary==='股票中性')factors={index:0,basis:1,commodity:0};else if(label.primary==='股票对冲')factors={index:.5,basis:.5,commodity:0};else if(label.primary==='CTA'||label.secondary==='商品'||label.secondary==='全品种')factors={index:0,basis:0,commodity:1};rows.push({fof:product.name,date:point.valuation_date,name:h.name,market:Number(h.market_value)||0,label,index:mapped.code,future:mapped.future,proxy:mapped.proxy,factors})})});return rows}
const RISK_SCENARIOS=[{name:'股市温和下跌',index:-.05,basis:.05,commodity:-.10},{name:'股市严重下跌',index:-.10,basis:.10,commodity:-.10},{name:'股市温和上涨',index:.05,basis:-.05,commodity:.10},{name:'股市强劲上涨',index:.10,basis:-.10,commodity:.10},{name:'贴水单独扩大10个百分点',index:0,basis:.10,commodity:0},{name:'贴水单独收窄10个百分点',index:0,basis:-.10,commodity:0}];
function stressResults(){const holdings=riskCurrentHoldings(),covered=holdings.filter(h=>h.factors),totalAssets=RAW.products.reduce((s,p)=>s+(((p.points||[]).slice(-1)[0]||{}).net_assets||0),0),coveredMarket=covered.reduce((s,h)=>s+h.market,0),results=RISK_SCENARIOS.map(scenario=>{const details=covered.map(h=>{const f=h.factors,rate=f.index*scenario.index+f.basis*scenario.basis+f.commodity*scenario.commodity,profit=h.market*rate;return Object.assign({},h,{rate,profit})}),profit=details.reduce((s,h)=>s+h.profit,0);return{scenario,profit,rate:coveredMarket?profit/coveredMarket*100:null,details}});return{holdings,covered,totalAssets,coveredMarket,uncovered:Math.max(0,totalAssets-coveredMarket),results}}
function riskTable(){const data=RAW.risk||{},holdings=riskCurrentHoldings(),exposure={};holdings.forEach(h=>{if(!h.factors||!h.index||!h.factors.index)return;exposure[h.index]=(exposure[h.index]||0)+h.market*h.factors.index});return['000852','000905','000300'].map(code=>{const item=(data.indices||{})[code]||{points:[]},v=historicalVar(item.points||[],p=>p.close);return`<tr><td>${escapeHtml((benchmarkIndex(code)||{}).name||code)}</td><td>${(item.points||[])[0]?(item.points[0].date+' → '+item.points[item.points.length-1].date):'暂无数据'}</td><td>${v.count}</td>${v.values.map(x=>`<td>${pct(x.value)}<div class=sub>${x.value==null?'无法计算':money((exposure[code]||0)*x.value/100)}</div></td>`).join('')}<td>${money(exposure[code]||0)}</td></tr>`}).join('')}
function stressHtml(){const data=stressResults(),coverage=data.totalAssets?data.coveredMarket/data.totalAssets*100:0;return`<div class=warn>固定线性敏感度：指增=对应指数1.0；中性=贴水1.0；股票对冲=指数0.5＋贴水0.5；CTA/商品=南华商品1.0。其他策略不强行估算。无直接股指期货的股票标签统一使用IM贴水代理。</div><div class=metrics><div class=metric><div class=label>最新底层覆盖市值</div><div class=value>${money(data.coveredMarket)}</div></div><div class=metric><div class=label>覆盖率（占最新顶层资产）</div><div class=value>${pct(coverage)}</div></div><div class=metric><div class=label>未覆盖资产</div><div class=value>${money(data.uncovered)}</div></div></div>${data.results.map(r=>{const strategies=new Map,fofs=new Map;r.details.forEach(h=>{strategies.set(h.label.primary,(strategies.get(h.label.primary)||0)+h.profit);fofs.set(h.fof,(fofs.get(h.fof)||0)+h.profit)});return`<details><summary><b>${r.scenario.name}</b>　模拟收益 <span class=${cls(r.profit)}>${money(r.profit)}</span>　覆盖持仓收益率 <span class=${cls(r.rate)}>${pct(r.rate)}</span></summary><p class=sub>指数 ${(r.scenario.index*100).toFixed(0)}%；贴水变化 ${(r.scenario.basis*100).toFixed(0)}个百分点；南华商品 ${(r.scenario.commodity*100).toFixed(0)}%</p><table><thead><tr><th>策略贡献</th><th>模拟收益</th></tr></thead><tbody>${[...strategies].sort((a,b)=>b[1]-a[1]).map(x=>`<tr><td>${x[0]}</td><td class=${cls(x[1])}>${money(x[1])}</td></tr>`).join('')}</tbody></table><table><thead><tr><th>FOF贡献</th><th>模拟收益</th></tr></thead><tbody>${[...fofs].sort((a,b)=>b[1]-a[1]).map(x=>`<tr><td>${x[0]}</td><td class=${cls(x[1])}>${money(x[1])}</td></tr>`).join('')}</tbody></table><table><thead><tr><th>FOF / 底层</th><th>标签 / 映射</th><th>市值</th><th>模拟收益率</th><th>模拟收益</th></tr></thead><tbody>${r.details.sort((a,b)=>b.profit-a.profit).map(h=>`<tr><td>${h.fof}<div class=sub>${h.name}</div></td><td>${h.label.primary} / ${h.label.secondary}<div class=sub>${h.future||'—'}${h.proxy?'（代理）':''}</div></td><td>${money(h.market)}</td><td class=${cls(h.rate)}>${pct(h.rate*100)}</td><td class=${cls(h.profit)}>${money(h.profit)}</td></tr>`).join('')}</tbody></table></details>`}).join('')}`}
function riskBasisTables(){const data=RAW.risk||{};return['IF','IC','IM'].map(prefix=>{const item=(data.futures||{})[prefix]||{points:[]};return`<h3>${prefix} ${escapeHtml(item.name||'')}</h3><table><thead><tr><th>期限</th><th>样本数</th><th>90%贴水VaR</th><th>95%贴水VaR</th><th>99%贴水VaR</th></tr></thead><tbody>${['当月','下月','当季','下季'].map(t=>{const v=basisVar(item.points||[],t);return`<tr><td>${t}</td><td>${v.count}</td>${v.values.map(x=>`<td>${x.value==null?'无法计算':x.value.toFixed(2)+'个百分点'}</td>`).join('')}</tr>`}).join('')}</tbody></table>`}).join('')}
function drawRiskBasis(win,prefix){const item=(((RAW.risk||{}).futures||{})[prefix])||{points:[]},selected=[...win.document.querySelectorAll('input[name=riskTenor]:checked')].map(x=>x.value),c=win.document.getElementById('riskBasisChart'),series=selected.map((t,i)=>({name:t,color:['#0f6b50','#b34432','#2867b2','#c6923c'][i],points:(item.points||[]).filter(p=>p[t]).map(p=>({date:p.date,value:p[t].value,contract:p[t].contract}))})),ctx=c.getContext('2d'),L=65,R=18,T=18,B=45,all=series.flatMap(s=>s.points);ctx.clearRect(0,0,c.width,c.height);if(!all.length){ctx.fillStyle='#68736d';ctx.fillText('暂无可用贴水数据',L,T+20);return}const dates=all.map(p=>p.date).sort(),start=new Date(dates[0]+'T00:00:00'),end=new Date(dates[dates.length-1]+'T00:00:00'),vals=all.map(p=>p.value),min=Math.min(...vals),max=Math.max(...vals),span=max-min||1,w=c.width-L-R,h=c.height-T-B,x=d=>L+(new Date(d+'T00:00:00')-start)/Math.max(end-start,DAY)*w,y=v=>T+(max-v)/span*h;ctx.strokeStyle='#e2e8f0';for(let i=0;i<=4;i++){const yy=T+h*i/4;ctx.beginPath();ctx.moveTo(L,yy);ctx.lineTo(L+w,yy);ctx.stroke();ctx.fillStyle='#68736d';ctx.fillText((max-span*i/4).toFixed(1)+'%',5,yy+4)}series.forEach(s=>{ctx.strokeStyle=s.color;ctx.lineWidth=2;ctx.beginPath();s.points.forEach((p,i)=>i?ctx.lineTo(x(p.date),y(p.value)):ctx.moveTo(x(p.date),y(p.value)));ctx.stroke()});let tip=win.document.getElementById('riskBasisTip');if(!tip){tip=win.document.createElement('div');tip.id='riskBasisTip';tip.style.cssText='position:fixed;display:none;pointer-events:none;background:#18201d;color:#fff;padding:8px;border-radius:6px;font-size:12px';win.document.body.appendChild(tip)}c.onmousemove=e=>{const rect=c.getBoundingClientRect(),cx=(e.clientX-rect.left)*c.width/rect.width,target=new Date(start.getTime()+Math.max(0,Math.min(1,(cx-L)/w))*(end-start)),day=target.toISOString().slice(0,10),rows=series.map(s=>{const p=s.points.filter(q=>q.date<=day).slice(-1)[0];return p?`<span style="color:${s.color}">●</span> ${s.name}：${p.value.toFixed(2)}%（${p.contract}）`:null}).filter(Boolean);tip.innerHTML=`<b>${day}</b><br>${rows.join('<br>')}`;tip.style.display='block';tip.style.left=Math.min(e.clientX+14,win.innerWidth-tip.offsetWidth-8)+'px';tip.style.top=Math.min(e.clientY+14,win.innerHeight-tip.offsetHeight-8)+'px'};c.onmouseleave=()=>tip.style.display='none'}
function openRisk(){const risk=RAW.risk||{},body=`<style>.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.metric{background:#f2f5f9;border-radius:9px;padding:12px}.value{font-size:20px;font-weight:700}.positive{color:#b34432}.negative{color:#0f7d63}.warn{background:#fff2d9;border-left:3px solid #c6923c;padding:10px;margin:10px 0}canvas{width:100%;height:340px;border:1px solid #d9ddd5;border-radius:8px}details{border:1px solid #d9ddd5;border-radius:8px;padding:10px;margin:10px 0}summary{cursor:pointer}</style><p class=sub>数据源：${escapeHtml(risk.source||'Wind Oracle数据库')}；更新时间：${escapeHtml(risk.updated_at||'暂无缓存')}。历史模拟一日VaR仅供风险分析参考。</p>${allRiskFactorsHtml()}<h2>四、股指期货年化贴水</h2><p class=sub>贴水率＝（现货－期货）÷现货×365÷剩余日历天数；正数为贴水，负数为升水。VaR为年化贴水率相邻日不利变化，单位百分点。</p><select id=riskFuture>${['IF','IC','IM'].map(x=>`<option>${x}</option>`).join('')}</select><span>${['当月','下月','当季','下季'].map(x=>`<label><input type=checkbox name=riskTenor value="${x}" checked>${x}</label>`).join('')}</span><canvas id=riskBasisChart width=1100 height=340></canvas>${riskBasisTables()}<h2>五、当前全部FOF底仓压力测试</h2>${stressHtml()}<p class=warn>压力测试为固定系数的线性估算，不包含波动率变化、相关性突变、流动性、费用及非线性风险，不构成损失预测或交易建议。</p>`,win=popup('风控页面',body);if(!win)return;const redraw=()=>drawRiskBasis(win,win.document.getElementById('riskFuture').value);win.document.getElementById('riskFuture').onchange=redraw;win.document.querySelectorAll('input[name=riskTenor]').forEach(x=>x.onchange=redraw);redraw()}
function addRiskControl(){const row=document.querySelector('.top-info');if(!row)return;const risk=document.createElement('button');risk.textContent='风控页面';risk.onclick=openRisk;row.appendChild(risk);const underlying=document.createElement('button');underlying.textContent='组合多空';underlying.onclick=openUnderlyingAssets;row.appendChild(underlying)}
function underlyingFofKey(x){return(x.fof_products||[]).length?(x.fof_products||[]).join('、'):'未匹配现有FOF持仓'}
function underlyingItemKey(x){return[x.product,x.valuation_date,x.source_file].join('|')}
function underlyingTotals(items){return{count:items.length,stock:items.reduce((s,x)=>s+(Number(x.stock_market_value)||0),0),long:items.reduce((s,x)=>s+(Number(x.index_futures_long)||0),0),short:items.reduce((s,x)=>s+(Number(x.index_futures_short)||0),0),exposure:items.reduce((s,x)=>s+(Number(x.long_exposure)||0),0)}}
function underlyingRows(items,selected){return items.slice().sort((a,b)=>{const group=underlyingFofKey(a).localeCompare(underlyingFofKey(b),'zh-CN');if(group)return group;const ar=a.long_exposure_ratio==null?-Infinity:Number(a.long_exposure_ratio),br=b.long_exposure_ratio==null?-Infinity:Number(b.long_exposure_ratio);return br-ar||a.product.localeCompare(b.product,'zh-CN')}).map(x=>{const key=underlyingItemKey(x);return`<tr><td><input class=underlying-check type=checkbox data-key="${encodeURIComponent(key)}" ${selected.has(key)?'checked':''}></td><td><b>${escapeHtml(x.product)}</b><div class=sub>${escapeHtml(x.source_file)}</div></td><td>${(x.fof_products||[]).length?(x.fof_products||[]).map(escapeHtml).join('<br>'):'未匹配现有FOF持仓'}</td><td>${x.valuation_date}</td><td>${money(x.stock_market_value)}</td><td>${money(x.index_futures_long)}</td><td>${money(x.index_futures_short)}</td><td class=${cls(x.long_exposure)}><b>${money(x.long_exposure)}</b></td><td>${x.long_exposure_ratio==null?'无法计算':pct(x.long_exposure_ratio)}</td><td>${(x.evidence||[]).map(e=>escapeHtml(e.code)+' '+escapeHtml(e.name)+'：'+money(e.market_value)).join('<br>')||'未识别到股票或股指期货科目'}</td></tr>`}).join('')}
function renderUnderlyingDate(win,date,reset=true){const items=((RAW.underlying_assets||{}).items||[]).filter(x=>x.valuation_date===date),keys=items.map(underlyingItemKey);if(reset||!win.underlyingSelection||win.underlyingSelection.date!==date)win.underlyingSelection={date,selected:new Set(keys)};const selected=win.underlyingSelection.selected,chosen=items.filter(x=>selected.has(underlyingItemKey(x))),totals=underlyingTotals(chosen),summary=win.document.getElementById('underlyingSummary'),body=win.document.getElementById('underlyingBody'),master=win.document.getElementById('underlyingSelectAll');summary.innerHTML=`<b>已选产品：${totals.count} / ${items.length}</b><b>股票市值合计：${money(totals.stock)}</b><b>股指多头合计：${money(totals.long)}</b><b>股指空头合计：${money(totals.short)}</b><b>多头敞口合计：${money(totals.exposure)}</b>`;body.innerHTML=items.length?underlyingRows(items,selected)+`<tr class=underlying-total><td></td><td colspan=3><b>已选${totals.count}项合计</b></td><td><b>${money(totals.stock)}</b></td><td><b>${money(totals.long)}</b></td><td><b>${money(totals.short)}</b></td><td class=${cls(totals.exposure)}><b>${money(totals.exposure)}</b></td><td>—</td><td>仅合计勾选项</td></tr>`:'<tr><td colspan=10>所选日期没有底层资产估值表。</td></tr>';if(master){master.checked=items.length>0&&totals.count===items.length;master.indeterminate=totals.count>0&&totals.count<items.length}body.querySelectorAll('.underlying-check').forEach(input=>input.onchange=()=>{const key=decodeURIComponent(input.dataset.key);input.checked?selected.add(key):selected.delete(key);renderUnderlyingDate(win,date,false)})}
function setUnderlyingSelection(win,checked){const state=win.underlyingSelection;if(!state)return;const items=((RAW.underlying_assets||{}).items||[]).filter(x=>x.valuation_date===state.date);state.selected=new Set(checked?items.map(underlyingItemKey):[]);renderUnderlyingDate(win,state.date,false)}
function openUnderlyingAssets(){const data=RAW.underlying_assets||{items:[],errors:[]},dates=[...new Set((data.items||[]).map(x=>x.valuation_date))].sort(),latest=dates[dates.length-1]||'',body=`<p class=sub>数据来自本机“底层资产”文件夹，只展示所选估值日期当天的真正底层产品；17只配置顶层FOF已按标准化产品名称精确排除。多头敞口＝股票市值＋股指期货多头名义市值－股指期货空头名义市值。勾选仅影响本页合计。</p><div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap"><label>估值日期 <select id=underlyingDate>${dates.map(d=>`<option ${d===latest?'selected':''}>${d}</option>`).join('')}</select></label><button id=underlyingSelectAllButton>全选</button><button id=underlyingSelectNoneButton>全不选</button></div><div id=underlyingSummary style="display:flex;gap:18px;flex-wrap:wrap;margin:10px 0"></div>${data.errors&&data.errors.length?`<div style="background:#fff2d9;padding:10px;margin:10px 0">${data.errors.map(x=>escapeHtml(x.file)+'：'+escapeHtml(x.error)).join('<br>')}</div>`:''}<div style="overflow:auto"><table><thead><tr><th><input id=underlyingSelectAll type=checkbox checked></th><th>底层产品</th><th>关联FOF</th><th>估值日期</th><th>股票市值</th><th>股指多头</th><th>股指空头</th><th>多头敞口</th><th>占净资产</th><th>计算依据</th></tr></thead><tbody id=underlyingBody></tbody></table></div>`,win=popup('组合多空',body);if(!win)return;const select=win.document.getElementById('underlyingDate'),all=win.document.getElementById('underlyingSelectAll'),allButton=win.document.getElementById('underlyingSelectAllButton'),noneButton=win.document.getElementById('underlyingSelectNoneButton');select.onchange=()=>renderUnderlyingDate(win,select.value,true);all.onchange=()=>setUnderlyingSelection(win,all.checked);allButton.onclick=()=>setUnderlyingSelection(win,true);noneButton.onclick=()=>setUnderlyingSelection(win,false);renderUnderlyingDate(win,latest,true);win.focus()}
function documentUnderlyingAssetChange(){const cards=document.querySelectorAll('.info-card'),method=cards[0]&&cards[0].querySelector('.info-body'),history=cards[2]&&cards[2].querySelector('.info-body');if(method)method.insertAdjacentHTML('beforeend','<p><b>组合多空：</b>读取本机“底层资产”文件夹中的底层产品估值表，可按实际估值日期筛选当天全部底层；先按关联FOF排序，同一FOF内按多头敞口占净资产比例从高到低排列。每个日期默认全选，可逐项勾选、全选或全不选；股票市值、股指多头、股指空头和多头敞口合计只使用当前勾选项，不影响其他页面。多头敞口＝股票市值＋股指期货多头名义市值－股指期货空头名义市值。</p>');if(history)history.insertAdjacentHTML('afterbegin','<div class="history-item"><b>2026-09-10 · 本次更新</b><br>组合多空新增逐项勾选、全选、全不选和勾选项合计，股票市值、股指多头、股指空头及多头敞口随选择即时重算。</div><div class="history-item"><b>2026-08-13 · 本次更新</b><br>组合多空增加估值日期筛选，默认最新日期；结果按关联FOF及多头敞口占净资产比例降序排列。</div>')}
